ALTER TABLE products ADD COLUMN IF NOT EXISTS details TEXT;
ALTER TABLE products ADD COLUMN IF NOT EXISTS specifications JSONB NOT NULL DEFAULT '{}'::jsonb;
-- Only fill blank details for known demo names/assets. Custom information survives.
UPDATE products p SET details = COALESCE(NULLIF(p.details, ''), demo.details),
 specifications = CASE WHEN p.specifications = '{}'::jsonb THEN demo.specs::jsonb ELSE p.specifications END
FROM (VALUES
('35 L Trail Backpack','/img/products/backpacks-01.jpg','Trail backpack with a 35 L capacity for day-long adventures. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Backpacks & Accessories", "Catalogue": "Illustrative demo item", "Capacity": "35 L (demo)"}'),
('20 L Daypack','/img/products/backpacks-02-daypack.jpg','Compact 20 L daypack for everyday outdoor essentials. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Backpacks & Accessories", "Catalogue": "Illustrative demo item", "Capacity": "20 L (demo)"}'),
('Pack Storage Pouch','/img/products/backpacks-03-pack-cover.jpg','Compact storage pouch for carrying small essentials on a backpack. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Backpacks & Accessories", "Catalogue": "Illustrative demo item"}'),
('Compact Trail Backpack','/img/products/backpacks-04-backpack.jpg','Compact backpack for day hikes and everyday outdoor essentials. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Backpacks & Accessories", "Catalogue": "Illustrative demo item"}'),
('Waterproof Hiking Jacket','/img/products/jackets-02-rain-jacket.jpg','A shell-style jacket for layering on outdoor walks. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Jackets & Layers", "Catalogue": "Illustrative demo item"}'),
('Fleece Midlayer','/img/products/jackets-03-fleece.jpg','A comfortable fleece layer for cooler days on the trail. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Jackets & Layers", "Catalogue": "Illustrative demo item"}'),
('Lightweight Hiking Jacket','/img/products/jackets-01.jpg','Lightweight hooded jacket for layering on cool-weather walks. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Jackets & Layers", "Catalogue": "Illustrative demo item"}'),
('Rain Poncho','/img/products/jackets-04-rain-poncho.jpg','Packable poncho for your outdoor kit. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Jackets & Layers", "Catalogue": "Illustrative demo item"}'),
('Mid-cut Hiking Boots','/img/products/boots-01.jpg','Supportive mid-cut hiking boots with a grippy outsole. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Footwear & Care", "Catalogue": "Illustrative demo item"}'),
('Trail Shoes','/img/products/boots-04-trail-shoes.jpg','Low-cut trail shoes for everyday walks and hikes. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Footwear & Care", "Catalogue": "Illustrative demo item"}'),
('Cushioned Hiking Socks','/img/products/boots-02-socks.jpg','Cushioned socks for comfortable trail walks. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Footwear & Care", "Catalogue": "Illustrative demo item"}'),
('Footwear Care Spray','/img/products/boots-03-waterproof-spray.jpg','A footwear care accessory for your hiking kit. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Footwear & Care", "Catalogue": "Illustrative demo item"}'),
('Trekking Poles (Pair)','/img/products/accessories-01-trekking-poles.jpg','Aluminium trekking poles with adjustable straps. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Accessories", "Catalogue": "Illustrative demo item"}'),
