('300 lm Head Torch','/img/products/accessories-04-headlamp.jpg','Compact head torch with an adjustable head strap. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Accessories", "Catalogue": "Illustrative demo item", "Light output": "300 lm (demo)"}'),
('Compact First Aid Kit','/img/products/accessories-03-first-aid.jpg','A compact first aid pouch for your trail essentials. This illustrative item is part of a portfolio catalogue. No goods are shipped. Product options, availability and performance ratings are not modelled in this demo.','{"Category": "Accessories", "Catalogue": "Illustrative demo item"}')) AS demo(name,image,details,specs)
WHERE p.name = demo.name AND p.image_url = demo.image;
